@@ -478,11 +478,27 @@ IDManifest::init (const char* data, const char* endOfData)

     _manifest.clear ();

-    if (manifestEntries <0)
+    if (manifestEntries < 0)
     {
         throw IEX_NAMESPACE::InputExc ("bad number of ChannelGroupsManifests in IDManifest");
     }

+    //
+    // channel-group manifests typically number from one to a few dozen
+    // (one per AOV); if a file declares substantially more than that,
+    // fail fast if there plainly isn't enough data left to hold them,
+    // rather than looping over an arbitrary declared count one entry at
+    // a time before eventually failing deep inside the loop
+    //
+    const size_t manifestTrackingHint = 64;
+    if ((size_t) manifestEntries > manifestTrackingHint &&
+        (size_t) (endOfData - data) < (size_t) manifestEntries)
+    {
+        throw IEX_NAMESPACE::InputExc (
+            "IDManifest declares more channel group manifests than the "
+            "remaining data could possibly contain");
+    }
+
     for (int manifestEntry = 0; manifestEntry < manifestEntries;
          ++manifestEntry)
     {

